def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count simple paths of exactly K moves, with every starting cell counted."""
    open_cells = [
        r * W + c
        for r in range(H)
        for c in range(W)
        if grid[r][c] == "."
    ]
    if K >= len(open_cells):
        return 0

    neighbors = [[] for _ in range(H * W)]
    for r in range(H):
        for c in range(W):
            cell = r * W + c
            if grid[r][c] != ".":
                continue
            if r > 0 and grid[r - 1][c] == ".":
                neighbors[cell].append(cell - W)
            if r + 1 < H and grid[r + 1][c] == ".":
                neighbors[cell].append(cell + W)
            if c > 0 and grid[r][c - 1] == ".":
                neighbors[cell].append(cell - 1)
            if c + 1 < W and grid[r][c + 1] == ".":
                neighbors[cell].append(cell + 1)

    total = 0

    def search(cell: int, remaining: int, visited: int) -> int:
        if remaining == 0:
            return 1
        result = 0
        for nxt in neighbors[cell]:
            bit = 1 << nxt
            if not visited & bit:
                result += search(nxt, remaining - 1, visited | bit)
        return result

    for start in open_cells:
        total += search(start, K, 1 << start)
    return total

MOD = 998244353


def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of divisor counts over all sequences of lengths 1..n."""
    if m == 1:
        return n % MOD

    # Only primes occurring in values up to m affect the divisor count.
    primes = []
    for x in range(2, m + 1):
        y = x
        for p in range(2, y + 1):
            if y % p == 0:
                if p not in primes:
                    primes.append(p)
                while y % p == 0:
                    y //= p
    r = len(primes)
    size = 1 << r

    # g[mask] is the sum, over one sequence element, of the product of
    # its prime exponents for the primes in mask.
    g = [0] * size
    for x in range(1, m + 1):
        exps = []
        y = x
        for p in primes:
            e = 0
            while y % p == 0:
                y //= p
                e += 1
            exps.append(e)
        for mask in range(1, size):
            prod = 1
            for j in range(r):
                if mask >> j & 1:
                    prod *= exps[j]
            g[mask] = (g[mask] + prod) % MOD

    # Sum products over set partitions of every prime subset, grouped by
    # the number of blocks. A block represents primes assigned to one slot.
    dp = [[0] * (r + 1) for _ in range(size)]
    dp[0][0] = 1
    for mask in range(1, size):
        bit = mask & -mask
        sub = mask
        while sub:
            if sub & bit:
                rest = mask ^ sub
                for b in range(1, r + 1):
                    dp[mask][b] = (dp[mask][b] + g[sub] * dp[rest][b - 1]) % MOD
            sub = (sub - 1) & mask

    coeff = [0] * (r + 1)
    for mask in range(size):
        for b in range(r + 1):
            coeff[b] = (coeff[b] + dp[mask][b]) % MOD

    # T[b] = sum_{k=1..n} (k)_b * m^(k-b), the bth derivative
    # of 1 + x + ... + x^n evaluated at x=m.
    # Obtain derivatives from the truncated Taylor expansion of the
    # geometric-series formula.
    fact = [1] * (r + 1)
    for j in range(1, r + 1):
        fact[j] = fact[j - 1] * j % MOD
    N = n + 1
    power = pow(m, N, MOD)
    numerator = [0] * (r + 1)
    for j in range(r + 1):
        choose = 1
        for t in range(j):
            choose = choose * ((N - t) % MOD) % MOD
        choose = choose * pow(fact[j], MOD - 2, MOD) % MOD
        numerator[j] = choose * pow(m, N - j, MOD) % MOD
    numerator[0] = (numerator[0] - 1) % MOD
    inv = pow(m - 1, MOD - 2, MOD)
    totals = [0] * (r + 1)
    for b in range(r + 1):
        q = 0
        for j in range(b + 1):
            q += numerator[j] * ((-1) ** (b - j)) * pow(inv, b - j + 1, MOD)
        totals[b] = (q % MOD) * fact[b] % MOD
    totals[0] = (totals[0] - 1) % MOD  # remove the k=0 empty sequence
    return sum(coeff[b] * totals[b] for b in range(r + 1)) % MOD

