from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine if the grid can be perfectly tiled by the available rectangles."""
    if h <= 0 or w <= 0:
        return False
    tiles = list(tiles[:n])
    if sum(a * b for a, b in tiles) < h * w:
        return False

    full = (1 << (h * w)) - 1
    # Each placement is a bit mask. Row-major first-empty-cell recursion means
    # any rectangle covering that cell must begin at that cell.
    placements = []
    for a, b in tiles:
        orientations = {(a, b), (b, a)}
        masks = []
        for ph, pw in orientations:
            if ph <= 0 or pw <= 0 or ph > h or pw > w:
                continue
            for r in range(h - ph + 1):
                for c in range(w - pw + 1):
                    mask = 0
                    for rr in range(r, r + ph):
                        row_start = rr * w + c
                        mask |= ((1 << pw) - 1) << row_start
                    masks.append((r, c, ph, pw, mask))
        placements.append(masks)

    memo = set()

    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        state = (occupied, used)
        if state in memo:
            return False

        # Area of all still-available tiles is an inexpensive necessary check.
        remaining_cells = h * w - occupied.bit_count()
        remaining_area = sum(a * b for i, (a, b) in enumerate(tiles) if not (used >> i) & 1)
        if remaining_area < remaining_cells:
            memo.add(state)
            return False

        first = next(i for i in range(h * w) if not (occupied >> i) & 1)
        r, c = divmod(first, w)
        for i, options in enumerate(placements):
            if (used >> i) & 1:
                continue
            seen = set()
            for pr, pc, ph, pw, mask in options:
                if pr != r or pc != c or (ph, pw) in seen:
                    continue
                seen.add((ph, pw))
                if occupied & mask == 0 and search(occupied | mask, used | (1 << i)):
                    return True
        memo.add(state)
        return False

    return search(0, 0)

