def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count integers in [start, finish] that end with s and use only digits <= limit."""
    if start > finish or not s or any(not ("0" <= ch <= "9") for ch in s):
        return 0
    if any(int(ch) > limit for ch in s):
        return 0

    suffix_value = int(s)
    suffix_len = len(s)

    def count_prefixes_at_most(bound: int, length: int) -> int:
        """Count length-digit positive prefixes, with digits <= limit, <= bound."""
        digits = str(bound)
        if len(digits) != length:
            return 0

        total = 0
        for i, char in enumerate(digits):
            bound_digit = int(char)
            lowest = 1 if i == 0 else 0
            choices = max(0, min(limit, bound_digit - 1) - lowest + 1)
            remaining = length - i - 1
            total += choices * (limit + 1) ** remaining
            if bound_digit < lowest or bound_digit > limit:
                return total
        return total + 1

    def count_up_to(n: int) -> int:
        if n < 0:
            return 0
        n_digits = len(str(n))
        max_prefix_len = n_digits - suffix_len
        if max_prefix_len < 0:
            return 0

        result = 0
        # With no prefix, the number is exactly s; it must itself be a
        # positive, canonical decimal representation.
        if suffix_len and s[0] != "0" and suffix_value <= n:
            result += 1

        # Prefix lengths shorter than the maximum produce fewer digits than n,
        # so every allowed prefix of that length is below n.
        for length in range(1, max_prefix_len):
            result += limit * (limit + 1) ** (length - 1)

        # For the maximum length, the prefix must not exceed n's leading part.
        if max_prefix_len >= 1:
            prefix_bound = n // (10 ** suffix_len)
            result += count_prefixes_at_most(prefix_bound, max_prefix_len)
        return result

    return count_up_to(finish) - count_up_to(start - 1)

