MOD = 998244353


def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically at most a, modulo 998244353."""
    limit = 2 * n + 2
    fact = [1] * (limit + 1)
    for i in range(1, limit + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (limit + 1)
    inv_fact[limit] = pow(fact[limit], MOD - 2, MOD)
    for i in range(limit, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def choose(top: int, bottom: int) -> int:
        if bottom < 0 or bottom > top or top < 0:
            return 0
        return fact[top] * inv_fact[bottom] % MOD * inv_fact[top - bottom] % MOD

    def prefix_weighted(L: int, top_t: int) -> int:
        r = L - 1
        if top_t < r:
            return 0
        return ((2 * L - 1 - r) * choose(top_t + 1, r + 1)
                - (r + 1) * choose(top_t + 1, r + 2)) % MOD

    def forests_in_range(L: int, low_k: int, high_k: int) -> int:
        low_k, high_k = max(low_k, 1), min(high_k, L)
        if low_k > high_k:
            return 0
        top_t = 2 * L - low_k - 1
        bottom_t = 2 * L - high_k - 1
        return ((prefix_weighted(L, top_t) - prefix_weighted(L, bottom_t - 1))
                % MOD * pow(L, MOD - 2, MOD) % MOD)

    answer = 0
    open_slots = 1
    processed = 0
    for i, bound in enumerate(a):
        if open_slots <= 0:
            break
        remaining = n - i - 1
        if remaining == 0:
            candidate = 1 - open_slots
            if 0 <= candidate < bound:
                answer += 1
        else:
            answer += forests_in_range(
                remaining, open_slots - 1, open_slots + bound - 2
            )
        answer %= MOD
        open_slots += bound - 1
        processed += 1
        if open_slots < 0:
            break

    if processed == n and open_slots == 0:
        answer = (answer + 1) % MOD
    return answer

from math import factorial


def count_k_palindromic_numbers(n: int, k: int) -> int:
    """Count good n-digit integers whose digits can form a k-divisible palindrome."""
    half_len = (n + 1) // 2
    seen = set()
    total = 0

    for prefix in range(10 ** (half_len - 1), 10**half_len):
        first_half = str(prefix)
        palindrome = first_half + first_half[: n // 2][::-1]
        if int(palindrome) % k:
            continue

        counts = [0] * 10
        for digit in palindrome:
            counts[ord(digit) - ord("0")] += 1
        signature = tuple(counts)
        if signature in seen:
            continue
        seen.add(signature)

        arrangements = factorial(n)
        for count in counts:
            arrangements //= factorial(count)
        if counts[0]:
            zero_leading = factorial(n - 1) // (
                factorial(counts[0] - 1) * product_factorials(counts[1:])
            )
            arrangements -= zero_leading
        total += arrangements

    return total


def product_factorials(counts):
    result = 1
    for count in counts:
        result *= factorial(count)
    return result

