from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Given N sections to monitor, return the minimum cost under the sensor limits.

    Sensors assigned to a section must cover its full length. Sensors can exceed
    that length; each sensor is assigned to one section.
    """
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # For each section, enumerate the two pure sensor options. Keeping the types
    # separate within a section also avoids treating surplus coverage as useful
    # for another section.
    dp = {(0, 0): 0}
    for length in sections[:n]:
        need1 = (length + l1 - 1) // l1
        need2 = (length + l2 - 1) // l2
        choices = []
        if need1 <= k1:
            choices.append((need1, 0, need1 * c1))
        if need2 <= k2:
            choices.append((0, need2, need2 * c2))
        if not choices:
            return -1

        next_dp = {}
        for (used1, used2), cost in dp.items():
            for add1, add2, add_cost in choices:
                new1, new2 = used1 + add1, used2 + add2
                if new1 <= k1 and new2 <= k2:
                    key = (new1, new2)
                    total = cost + add_cost
                    if total < next_dp.get(key, float("inf")):
                        next_dp[key] = total
        dp = next_dp
        if not dp:
            return -1

    return min(dp.values()) if dp else -1

