from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are arranged in alternating horizontal and vertical strips in
    K-by-K blocks. The returned distance is in tile adjacencies.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk = (S_y % K) if (si + sj) % 2 == 0 else (S_x % K)
    tk = (T_y % K) if (ti + tj) % 2 == 0 else (T_x % K)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    # Distances in very large block rectangles have a simple strip-density
    # limit; avoid constructing a graph proportional to the coordinate span.
    width = abs(ti - si) + 1
    height = abs(tj - sj) + 1
    if width * height > 20000:
        dx, dy = abs(T_x - S_x), abs(T_y - S_y)
        return (dx + K - 1) // K + (dy + K - 1) // K

    xmin, xmax = min(si, ti) - 1, max(si, ti) + 1
    ymin, ymax = min(sj, tj) - 1, max(sj, tj) + 1
    indices = {}
    for i in range(xmin, xmax + 1):
        for j in range(ymin, ymax + 1):
            vals = {0, K - 1}
            if (i, j) == (si, sj):
                vals.add(sk)
            if (i, j) == (ti, tj):
                vals.add(tk)
            indices[(i, j)] = sorted(vals)

    adj = {}
    def node(cell, k):
        return (cell[0], cell[1], k)

    for cell, vals in indices.items():
        ns = [node(cell, k) for k in vals]
        for n in ns:
            adj[n] = []
        for a in range(len(vals)):
            for b in range(a + 1, len(vals)):
                u, v = ns[a], ns[b]
                w = vals[b] - vals[a]
                adj[u].append((v, w))
                adj[v].append((u, w))

    def link(u, v):
        adj[u].append((v, 1))
        adj[v].append((u, 1))

    # Vertical block boundaries.
    for i in range(xmin, xmax):
        for j in range(ymin, ymax + 1):
            left, right = (i, j), (i + 1, j)
            if (i + j) % 2 == 0:  # horizontal strips meet the left edge of V
                for k in indices[left]:
                    link(node(left, k), node(right, 0))
            else:  # right edge of V meets every horizontal strip
                for k in indices[right]:
                    link(node(left, K - 1), node(right, k))

    # Horizontal block boundaries.
    for i in range(xmin, xmax + 1):
        for j in range(ymin, ymax):
            lower, upper = (i, j), (i, j + 1)
            if (i + j) % 2 == 0:  # every H strip meets every V strip
                for a in indices[lower]:
                    for b in indices[upper]:
                        link(node(lower, a), node(upper, b))
            else:  # every V strip meets the bottom H strip
                for k in indices[lower]:
                    link(node(lower, k), node(upper, 0))

    start, target = node((si, sj), sk), node((ti, tj), tk)
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        if u == target:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist.get(v, 10**100):
                dist[v] = nd
                heappush(heap, (nd, v))
    return dist[target]

