def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct in-degree sequences obtainable from orientations of the graph."""
    mod = 998244353

    # A cycle edge state e_i is 1 when edge i -> i+1 points forward, and
    # 0 otherwise. At vertex i the cycle contributes 1 + e_(i-1) - e_i.
    # If s[i] is 1, its spoke adds an independently chosen 0 or 1.
    #
    # For a fixed sequence of degrees on vertices 0..n-1, track the relation
    # between the initial and current cycle-edge states. There are only four
    # possible states, encoded as a 2x2 Boolean matrix. Determinizing these
    # relations counts each degree sequence once, even if several orientations
    # produce it. A degree sequence closes around the cycle exactly when the
    # final relation contains a diagonal entry.
    def compose(left: int, right: int) -> int:
        result = 0
        for start in range(2):
            row = (left >> (start * 2)) & 3
            out = 0
            if row & 1:
                out |= right & 3
            if row & 2:
                out |= (right >> 2) & 3
            result |= out << (start * 2)
        return result

    # For each spoke flag and degree value, construct the one-step relation.
    step = [[0] * 4 for _ in range(2)]
    for has_spoke in range(2):
        for degree in range(4):
            relation = 0
            for previous in range(2):
                for current in range(2):
                    for spoke in range(has_spoke + 1):
                        if degree == 1 + previous - current + spoke:
                            relation |= 1 << (previous * 2 + current)
            step[has_spoke][degree] = relation

    # Combine equal target relations, retaining how many distinct degree
    # values lead there; those values are still distinct sequence symbols.
    transitions = [[[] for _ in range(16)] for _ in range(2)]
    for has_spoke in range(2):
        for relation in range(16):
            counts = {}
            for degree in range(4):
                target = compose(relation, step[has_spoke][degree])
                counts[target] = counts.get(target, 0) + 1
            transitions[has_spoke][relation] = list(counts.items())

    # Identity relation: each of the two possible initial states maps to itself.
    dp = [0] * 16
    dp[9] = 1
    for bit in s:
        nxt = [0] * 16
        for relation, ways in enumerate(dp):
            if ways:
                for target, multiplicity in transitions[bit == "1"][relation]:
                    nxt[target] = (nxt[target] + ways * multiplicity) % mod
        dp = nxt

    return sum(dp[relation] for relation in range(16) if relation & 9) % mod

