from functools import lru_cache
from math import isqrt

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M positive integer sequences with product at most N and
    whose product has divisor sum divisible by 3.
    """
    # Only primes up to sqrt(N) are needed for composite factor prefixes.
    limit = isqrt(N)
    sieve = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * (((limit - start) // p) + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]
    # Include primes up through N for prime-counting's small-x base cases.
    # For x <= limit, direct sieve counts are available from this list.
    pi1 = [0] * (limit + 1)
    pi2 = [0] * (limit + 1)
    c1 = c2 = 0
    for x in range(limit + 1):
        if x >= 2 and sieve[x]:
            if x % 3 == 1:
                c1 += 1
            elif x % 3 == 2:
                c2 += 1
        pi1[x], pi2[x] = c1, c2

    # Number of integers <= x in residue r modulo 3 that avoid the first a
    # primes other than 3. Inclusion-exclusion gives prime counts after
    # sieving through sqrt(x).
    small_primes = [p for p in primes if p != 3]

    @lru_cache(None)
    def phi(x: int, a: int, r: int) -> int:
        if x <= 0:
            return 0
        # Count the progression directly once there are no sieving primes.
        if a == 0:
            first = r if r else 3
            if first > x:
                return 0
            return (x - first) // 3 + 1
        p = small_primes[a - 1]
        inv = 1 if p % 3 == 1 else 2
        return phi(x, a - 1, r) - phi(x // p, a - 1, (r * inv) % 3)

    @lru_cache(None)
    def prime_count_residue(x: int, r: int) -> int:
        if x < 2:
            return 0
        if x <= limit:
            return pi1[x] if r == 1 else pi2[x]
        # All composite numbers <= x have a prime factor <= sqrt(x).
        a = 0
        root = isqrt(x)
        while a < len(small_primes) and small_primes[a] <= root:
            a += 1
        # The only surviving non-prime in class 1 is the integer 1, but our
        # residue-class convention starts at 1; class 1's count includes it.
        v = phi(x, a, r)
        return v - (1 if r == 1 else 0)

    def pi_range(lo: int, hi: int, r: int) -> int:
        if hi < lo:
            return 0
        return prime_count_residue(hi, r) - prime_count_residue(lo - 1, r)

    invs = [0, 1]
    max_exp = 0
    q = 2
    while q <= N:
        q *= 2
        max_exp += 1
    for i in range(2, max_exp + 1):
        invs.append(MOD - (MOD // i) * invs[MOD % i] % MOD)

    # H(i, x, s) sums over residual integers whose prime factors are all
    # greater than primes[i-1], with current divisor-sum residue s.
    @lru_cache(None)
    def solve(i: int, x: int, s: int) -> int:
        ans = 1 if s == 0 else 0  # choose no further factors
        if x <= 1:
            return ans
        lower = primes[i] if i < len(primes) else x + 1
        root = isqrt(x)
        # A remaining prime above sqrt(x) can occur only to exponent one.
        lo = max(lower, root + 1)
        if lo <= x:
            # q == 1 (mod 3): sigma(q) == 2; q == 2: sigma(q) == 0.
            if s == 0:
                ans += M * (pi_range(lo, x, 1) + (1 if lo <= 3 <= x else 0))
            ans += M * pi_range(lo, x, 2)
            ans %= MOD

        j = i
        while j < len(primes):
            p = primes[j]
            if p <= lower:
                j += 1
                continue
            if p > root:
                break
            power = p
            e = 1
            weight = M % MOD
            while power <= x:
                if p == 3:
                    sig = 1
                elif p % 3 == 1:
                    sig = (e + 1) % 3
                else:
                    sig = 0 if e & 1 else 1
                ans += weight * solve(j + 1, x // power, (s * sig) % 3)
                power *= p
                e += 1
                weight = weight * (M + e - 1) % MOD * invs[e] % MOD
            ans %= MOD
            j += 1
        return ans % MOD

    return solve(0, N, 1) % MOD

