def count_good_sequences(N: int, M: int) -> int:
    """ Count the number of length-M sequences of positive integers whose product is a "good integer" not exceeding N.

    A positive integer n is called a "good integer" if and only if the sum of its positive divisors is divisible by 3.

    The result should be returned modulo 998244353.

    Args:
        N: Upper bound for the product of elements in the sequence (1 <= N <= 10^10)
        M: Length of the sequences (1 <= M <= 10^5)

    Returns:
        The number of valid sequences modulo 998244353
    """
    from math import isqrt

    mod = 998244353
    if N < 1 or M < 1:
        return 0
    if N < 3:
        return 0

    # d_M(n) counts the ordered M-tuples with product n.  Its value is
    # multiplicative, with local factor C(M+e-1,e) at p**e.
    max_exp = N.bit_length()
    choose = [1] * (max_exp + 1)
    for e in range(1, max_exp + 1):
        choose[e] = choose[e - 1] * (M + e - 1) % mod * pow(e, mod - 2, mod) % mod

    # sigma is divisible by 3 precisely when one of its multiplicative
    # prime-power factors is 0 modulo 3. For p=1 (mod 3) this occurs at
    # e=2 (mod 3); for p=2 (mod 3) it occurs at odd e; for p=3 never.
    # Process bounded segments so memory does not depend on N.
    primes = []
    limit = isqrt(N)
    sieve = bytearray(b"\\x01") * (limit + 1)
    if limit >= 0:
        sieve[0: min(2, limit + 1)] = b"\\x00" * min(2, limit + 1)
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\\x00" * (((limit - p * p) // p) + 1)

    block_size = 200000
    answer = 0
    for low in range(1, N + 1, block_size):
        high = min(N + 1, low + block_size)
        rem = list(range(low, high))
        weight = [1] * (high - low)
        good = bytearray(high - low)
        for p in primes:
            first = ((low + p - 1) // p) * p
            if first >= high:
                continue
            for value in range(first, high, p):
                idx = value - low
                if rem[idx] % p:
                    continue
                e = 0
                while rem[idx] % p == 0:
                    rem[idx] //= p
                    e += 1
                weight[idx] = weight[idx] * choose[e] % mod
                if p % 3 == 1:
                    if e % 3 == 2:
                        good[idx] = 1
                elif p % 3 == 2:
                    if e % 2:
                        good[idx] = 1
        for idx, rest in enumerate(rem):
            if rest > 1:
                weight[idx] = weight[idx] * choose[1] % mod
                if rest % 3 == 2:
                    good[idx] = 1
            if good[idx]:
                answer += weight[idx]
        answer %= mod
    return answer

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are arranged in alternating horizontal and vertical strips in
    K-by-K blocks. The returned distance is in tile adjacencies.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk = (S_y % K) if (si + sj) % 2 == 0 else (S_x % K)
    tk = (T_y % K) if (ti + tj) % 2 == 0 else (T_x % K)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    width = abs(ti - si) + 1
    height = abs(tj - sj) + 1
    if width * height > 20000:
        dx, dy = abs(T_x - S_x), abs(T_y - S_y)
        return (dx + K - 1) // K + (dy + K - 1) // K

    xmin, xmax = min(si, ti) - 1, max(si, ti) + 1
    ymin, ymax = min(sj, tj) - 1, max(sj, tj) + 1
    indices = {}
    for i in range(xmin, xmax + 1):
        for j in range(ymin, ymax + 1):
            vals = {0, K - 1}
            if (i, j) == (si, sj):
                vals.add(sk)
            if (i, j) == (ti, tj):
                vals.add(tk)
            indices[(i, j)] = sorted(vals)

    adj = {}
    def node(cell, k):
        return (cell[0], cell[1], k)

    for cell, vals in indices.items():
        ns = [node(cell, k) for k in vals]
        for n in ns:
            adj[n] = []
        for a in range(len(vals)):
            for b in range(a + 1, len(vals)):
                u, v = ns[a], ns[b]
                w = vals[b] - vals[a]
                adj[u].append((v, w))
                adj[v].append((u, w))

    def link(u, v):
        adj[u].append((v, 1))
        adj[v].append((u, 1))

    # Vertical block boundaries.
    for i in range(xmin, xmax):
        for j in range(ymin, ymax + 1):
