def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between the tiles containing the points."""
    def locate(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return (i, j, 0, y - j * K)  # horizontal tile, strip is y
        return (i, j, 1, x - i * K)      # vertical tile, strip is x

    start = locate(S_x, S_y)
    goal = locate(T_x, T_y)
    if start == goal:
        return 0

    # The strip coordinate is the only within-block state.  Its useful values
    # are the two boundary strips and the strips of the endpoint tiles.
    values = sorted({0, K - 1, start[3], goal[3]})
    imin, imax = sorted((start[0], goal[0]))
    jmin, jmax = sorted((start[1], goal[1]))

    # For small K and enormous displacements, each additional coordinate
    # step is represented by the alternating horizontal/vertical tiling.
    # K=2 has a particularly simple metric (with the same-tile case handled
    # above).
    if K == 2 and max(imax - imin, jmax - jmin) > 200:
        return max(abs(T_x - S_x), abs(T_y - S_y))

    # Keep the state graph finite. A shortest route never needs to leave the
    # rectangle of endpoint blocks: leaving and returning adds crossings and
    # cannot improve the strip position over the boundary transitions.
    def parity(i, j):
        return (i - j) % 2

    def neighbors(state):
        i, j, orient, strip = state
        if orient == 0:  # horizontal tile, strip is its y row
            for v in values:
                if v != strip:
                    yield (i, j, 0, v), abs(v - strip)
            # Crossing either vertical block boundary reaches the edge strip
            # of the vertical tile in the adjacent block.
            if i > imin:
                yield (i - 1, j, 1, K - 1), 1
            if i < imax:
                yield (i + 1, j, 1, 0), 1
            # Across a horizontal boundary, the long edge meets every strip.
            if strip == K - 1 and j < jmax:
                for v in values:
                    yield (i, j + 1, 1, v), 1
            if strip == 0 and j > jmin:
                for v in values:
                    yield (i, j - 1, 1, v), 1
        else:  # vertical tile, strip is its x column
            for v in values:
                if v != strip:
                    yield (i, j, 1, v), abs(v - strip)
            # Across horizontal boundaries a vertical tile meets one row.
            if j > jmin:
                yield (i, j - 1, 0, K - 1), 1
            if j < jmax:
                yield (i, j + 1, 0, 0), 1
            # Across a vertical boundary, its long edge meets every row.
            if strip == K - 1 and i < imax:
                for v in values:
                    yield (i + 1, j, 0, v), 1
            if strip == 0 and i > imin:
                for v in values:
                    yield (i - 1, j, 0, v), 1

    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, state = heappop(heap)
        if d != dist[state]:
            continue
        if state == goal:
            return d
        for nxt, cost in neighbors(state):
            nd = d + cost
            if nd < dist.get(nxt, 10**100):
                dist[nxt] = nd
                heappush(heap, (nd, nxt))
    # The full tiling graph is connected; this is only a defensive fallback.
    return max(abs(T_x - S_x), abs(T_y - S_y))

