def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk = S_y % K if (si + sj) % 2 == 0 else S_x % K
    tk = T_y % K if (ti + tj) % 2 == 0 else T_x % K
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    width, height = abs(ti - si) + 1, abs(tj - sj) + 1
    if width * height > 20000:
        dx, dy = abs(T_x - S_x), abs(T_y - S_y)
        return (dx + K - 1) // K + (dy + K - 1) // K

    margin = 3
    xmin, xmax = min(si, ti) - margin, max(si, ti) + margin
    ymin, ymax = min(sj, tj) - margin, max(sj, tj) + margin
    indices = {}
    for i in range(xmin, xmax + 1):
        for j in range(ymin, ymax + 1):
            vals = {0, K - 1}
            if (i, j) == (si, sj):
                vals.add(sk)
            if (i, j) == (ti, tj):
                vals.add(tk)
            indices[i, j] = sorted(vals)

    adj = {}
    def node(cell, k):
        return cell[0], cell[1], k

    for cell, vals in indices.items():
        ns = [node(cell, k) for k in vals]
        for n in ns:
            adj[n] = []
        for a in range(len(vals)):
            for b in range(a + 1, len(vals)):
                u, v = ns[a], ns[b]
                w = vals[b] - vals[a]
                adj[u].append((v, w))
                adj[v].append((u, w))

    def link(u, v):
        adj[u].append((v, 1))
        adj[v].append((u, 1))

    for i in range(xmin, xmax):
        for j in range(ymin, ymax + 1):
            left, right = (i, j), (i + 1, j)
            if (i + j) % 2 == 0:
                for k in indices[left]:
                    link(node(left, k), node(right, 0))
            else:
                for k in indices[right]:
                    link(node(left, K - 1), node(right, k))

    for i in range(xmin, xmax + 1):
        for j in range(ymin, ymax):
            lower, upper = (i, j), (i, j + 1)
            if (i + j) % 2 == 0:
                for k in indices[upper]:
                    link(node(lower, K - 1), node(upper, k))
            else:
                for k in indices[lower]:
                    link(node(lower, k), node(upper, 0))

    start, target = node((si, sj), sk), node((ti, tj), tk)
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        if u == target:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist.get(v, 10**100):
                dist[v] = nd
                heappush(heap, (nd, v))
    return dist[target]

from collections import deque


def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    start = bytes((0 if ch == "B" else 1) for ch in s) + b"\x02\x02"
    target = bytes((0 if ch == "B" else 1) for ch in t) + b"\x02\x02"
    if start == target:
        return 0
    distance = {start: 0}
    queue = deque([start])
    while queue:
        state = queue.popleft()
        next_distance = distance[state] + 1
        holes = [i for i, value in enumerate(state) if value == 2]
        h0, h1 = holes
        for i in range(n + 1):
            a, b = state[i], state[i + 1]
            if a == 2 or b == 2:
                continue
            next_state = bytearray(state)
            next_state[h0], next_state[h1] = a, b
            next_state[i], next_state[i + 1] = 2, 2
            successor = bytes(next_state)
            if successor == target:
                return str(next_distance)
            if successor not in distance:
                distance[successor] = next_distance
                queue.append(successor)
    return -1

