import sys
from functools import lru_cache
from math import isqrt

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product has divisor sum divisible by 3."""
    sys.setrecursionlimit(20000)
    limit = isqrt(N)
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * (((limit - start) // p) + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]

    pi1 = [0] * (limit + 1)
    pi2 = [0] * (limit + 1)
    c1 = c2 = 0
    for x in range(limit + 1):
        if x >= 2 and sieve[x]:
            if x % 3 == 1:
                c1 += 1
            elif x % 3 == 2:
                c2 += 1
        pi1[x], pi2[x] = c1, c2

    small_primes = [p for p in primes if p != 3]

    @lru_cache(None)
    def phi(x: int, a: int, r: int) -> int:
        if x <= 0:
            return 0
        if a == 0:
            first = r if r else 3
            return 0 if first > x else (x - first) // 3 + 1
        p = small_primes[a - 1]
        inv = 1 if p % 3 == 1 else 2
        return phi(x, a - 1, r) - phi(x // p, a - 1, (r * inv) % 3)

    @lru_cache(None)
    def prime_count_residue(x: int, r: int) -> int:
        if x < 2:
            return 0
        if x <= limit:
            return pi1[x] if r == 1 else pi2[x]
        root = isqrt(x)
        a = 0
        while a < len(small_primes) and small_primes[a] <= root:
            a += 1
        # The sifted count contains surviving primes and 1, but omits the
        # small primes used in the sieve because each is divisible by itself.
        small = pi1[root] if r == 1 else pi2[root]
        return phi(x, a, r) + small - (1 if r == 1 else 0)

    def pi_range(lo: int, hi: int, r: int) -> int:
        if hi < lo:
            return 0
        return prime_count_residue(hi, r) - prime_count_residue(lo - 1, r)

    max_exp = N.bit_length()
    invs = [0, 1]
    for e in range(2, max_exp + 1):
        invs.append(MOD - (MOD // e) * invs[MOD % e] % MOD)

    @lru_cache(None)
    def solve(i: int, x: int, s: int) -> int:
        ans = 1 if s == 0 else 0
        if x <= 1:
            return ans
        previous = primes[i - 1] if i else 1
        root = isqrt(x)
        lo = max(previous + 1, root + 1)
        if lo <= x:
            if s == 0:
                ans += M * (pi_range(lo, x, 1) + (1 if lo <= 3 <= x else 0))
            ans += M * pi_range(lo, x, 2)

        j = i
        while j < len(primes):
            p = primes[j]
            if p > root:
                break
            power = p
            e = 1
            weight = M % MOD
            while power <= x:
                if p == 3:
                    sig = 1
                elif p % 3 == 1:
                    sig = (e + 1) % 3
                else:
                    sig = 0 if e & 1 else 1
                ans += weight * solve(j + 1, x // power, (s * sig) % 3)
                power *= p
                e += 1
                if power <= x:
                    weight = weight * (M + e - 1) % MOD * invs[e] % MOD
            j += 1
        return ans % MOD

    return solve(0, N, 1) % MOD

