def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    tiles = list(tiles[:n])
    if sum(a * b for a, b in tiles) < h * w:
        return False
    full = (1 << (h * w)) - 1
    placements = []
    for a, b in tiles:
        masks = []
        for ph, pw in {(a, b), (b, a)}:
            if ph <= 0 or pw <= 0 or ph > h or pw > w:
                continue
            for r in range(h - ph + 1):
                for c in range(w - pw + 1):
                    mask = sum(((1 << pw) - 1) << (rr * w + c) for rr in range(r, r + ph))
                    masks.append((mask, r, c, ph, pw))
        placements.append(masks)
    memo = set()
    path = []
    def search(occupied, used):
        if occupied == full:
            print("WITNESS", path)
            return True
        state = (occupied, used)
        if state in memo:
            return False
        remaining = h * w - occupied.bit_count()
        if sum(a*b for i,(a,b) in enumerate(tiles) if not (used >> i)&1) < remaining:
            memo.add(state)
            return False
        first = next(i for i in range(h*w) if not (occupied >> i)&1)
        bit = 1 << first
        for i, options in enumerate(placements):
            if (used >> i)&1:
                continue
            for mask,r,c,ph,pw in options:
                if mask & bit and not (occupied & mask):
                    path.append((i,r,c,ph,pw))
