from functools import lru_cache
from math import comb


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words over 1..K whose only missing length-M subsequence is X.

    The result is returned modulo 998244353.
    """
    mod = 998244353

    @lru_cache(None)
    def onto(q: int, n: int) -> int:
        """Words of length n over q letters using every letter."""
        if n < 0:
            return 0
        return sum(
            (-1 if i & 1 else 1) * comb(q, i) * pow(q - i, n, mod)
            for i in range(q + 1)
        ) % mod

    @lru_cache(None)
    def tail_after_first(pattern: tuple[int, ...], q: int, length: int) -> int:
        """Words whose first completion of pattern leaves an onto suffix."""
        r = len(pattern)
        if length < r:
            return 0
        # Greedy subsequence matching state for prefixes before the first
        # completion. At state j, exactly one alphabet symbol advances it.
        dp = [0] * r
        dp[0] = 1
        answer = 0
        for used in range(length):
            # Completion at position used+1 is possible precisely from state
            # r-1, using the one symbol pattern[-1].
            if used + 1 >= r:
                answer += dp[r - 1] * onto(q, length - used - 1)
            ndp = [0] * r
            for j, value in enumerate(dp):
                ndp[j] = (ndp[j] + value * (q - 1)) % mod
                if j + 1 < r:
                    ndp[j + 1] = (ndp[j + 1] + value) % mod
            dp = ndp
        return answer % mod

    @lru_cache(None)
    def count(n: int, m: int, k: int, forbidden: tuple[int, ...]) -> int:
        # The constant word a^m is required for every a unless it is X.
        lower_bound = m * k - (1 if len(set(forbidden)) == 1 else 0)
        if n < lower_bound:
            return 0

        if m == 1:
            # Avoid the forbidden letter and use all other letters.
            return onto(k - 1, n)

        prefix_pattern = forbidden[:-1]
        last = forbidden[-1]
        q = k - 1
        answer = 0

        # Let t be the length before the last occurrence of last.
        # The prefix contains every (m-1)-word except prefix_pattern.
        for t in range(n):
            ways_prefix = count(t, m - 1, k, prefix_pattern)
            if not ways_prefix:
                continue
            suffix_length = n - t - 1

            if prefix_pattern[-1] == last:
                # The distinguished prefix is completed at the last letter.
                ways_suffix = onto(q, suffix_length)
            elif last not in prefix_pattern:
                # It is first completed in the suffix, which has no last;
                # all other letters must occur after that first completion.
                ways_suffix = tail_after_first(
                    prefix_pattern, q, suffix_length
                )
            else:
                # A last inside the prefix pattern cannot be completed before
                # or after its final occurrence.
                continue

            answer = (answer + ways_prefix * ways_suffix) % mod

        return answer

    return count(N, M, K, tuple(X))

from functools import lru_cache
from math import isqrt

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product has divisor sum divisible by 3."""
    root_n = isqrt(N)
    sieve = bytearray(b"\x01") * (root_n + 1)
    sieve[0] = 0
    if root_n >= 1:
        sieve[1] = 0
    for p in range(2, isqrt(root_n) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:root_n + 1:p] = b"\x00" * (((root_n - start) // p) + 1)
    primes = [p for p in range(2, root_n + 1) if sieve[p]]

    # Prime counts by residue class for all distinct floor(N/k) values.
    values = list(range(1, root_n + 1))
    values.extend(N // i for i in range(root_n, 0, -1) if N // i > root_n)
    index = {v: i for i, v in enumerate(values)}
    g1 = [0] * len(values)
    g2 = [0] * len(values)
    for i, x in enumerate(values):
        n1 = (x - 1) // 3 + 1 if x >= 1 else 0
        n2 = (x - 2) // 3 + 1 if x >= 2 else 0
        g1[i] = n1 - 1  # exclude 1
        g2[i] = n2

    # Sieve composites from the residue-class candidate counts. Multiples
    # of 3 cannot lie in either class, so p=3 is intentionally skipped.
    for p in primes:
        if p == 3:
            continue
        p2 = p * p
        pi1_below = g1[index[p - 1]]
        pi2_below = g2[index[p - 1]]
        if p % 3 == 1:
            for ix in range(len(values) - 1, -1, -1):
                x = values[ix]
                if x < p2:
                    break
                j = index[x // p]
                g1[ix] -= g1[j] - pi1_below
                g2[ix] -= g2[j] - pi2_below
        else:
            for ix in range(len(values) - 1, -1, -1):
                x = values[ix]
                if x < p2:
                    break
                j = index[x // p]
                g1[ix] -= g2[j] - pi2_below
                g2[ix] -= g1[j] - pi1_below

    pi_small_1 = [0] * (root_n + 1)
    pi_small_2 = [0] * (root_n + 1)
    c1 = c2 = 0
    for x in range(root_n + 1):
        if x >= 2 and sieve[x]:
            if x % 3 == 1:
                c1 += 1
            elif x % 3 == 2:
                c2 += 1
        pi_small_1[x] = c1
        pi_small_2[x] = c2

    def pi_r(x: int, r: int) -> int:
        if x < 2:
            return 0
        if x <= root_n:
            return pi_small_1[x] if r == 1 else pi_small_2[x]
        return (g1 if r == 1 else g2)[index[x]]

    max_exp = N.bit_length()
    invs = [0, 1]
    for e in range(2, max_exp + 1):
        invs.append(MOD - (MOD // e) * invs[MOD % e] % MOD)

    @lru_cache(None)
    def solve(i: int, x: int, s: int) -> int:
        ans = 1 if s == 0 else 0
        if x <= 1:
            return ans
        previous = primes[i - 1] if i else 1
        root = isqrt(x)
        tail_start = max(previous, root)
        if s == 0:
            ans += M * (pi_r(x, 1) - pi_r(tail_start, 1)
                        + (1 if previous < 3 <= x and root < 3 else 0))
        ans += M * (pi_r(x, 2) - pi_r(tail_start, 2))

        j = i
        while j < len(primes) and primes[j] <= root:
            p = primes[j]
            power = p
            e = 1
            weight = M % MOD
            while power <= x:
                if p == 3:
                    sig = 1
                elif p % 3 == 1:
                    sig = (e + 1) % 3
                else:
                    sig = 0 if e & 1 else 1
                ans += weight * solve(j + 1, x // power, (s * sig) % 3)
                power *= p
                e += 1
                if power <= x:
                    weight = weight * (M + e - 1) % MOD * invs[e] % MOD
            j += 1
        return ans % MOD

    return solve(0, N, 1) % MOD

from functools import lru_cache
from math import comb


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words over 1..K whose only missing length-M subsequence is X.

    The result is returned modulo 998244353.
    """
    mod = 998244353

    @lru_cache(None)
    def onto(q: int, n: int) -> int:
        """Words of length n over q letters using every letter."""
        if n < 0:
            return 0
        return sum(
            (-1 if i & 1 else 1) * comb(q, i) * pow(q - i, n, mod)
            for i in range(q + 1)
        ) % mod

    @lru_cache(None)
    def tail_after_first(last_pattern_letter: int, q: int, length: int) -> int:
        """Suffixes where the next needed pattern letter is first, then all q letters occur."""
        answer = 0
        for before in range(length):
            # Before the first matching letter, each position has q-1 choices.
            answer += pow(q - 1, before, mod) * onto(q, length - before - 1)
        return answer % mod

    @lru_cache(None)
    def count(n: int, m: int, k: int, forbidden: tuple[int, ...]) -> int:
        # The constant word a^m is required for every a unless it is X.
        lower_bound = m * k - (1 if len(set(forbidden)) == 1 else 0)
        if n < lower_bound:
            return 0

        if m == 1:
            # Avoid the forbidden letter and use all other letters.
            return onto(k - 1, n)

        prefix_pattern = forbidden[:-1]
        last = forbidden[-1]
        q = k - 1
        answer = 0

        # The last occurrence of last divides the word into a prefix which
        # misses prefix_pattern and a suffix over the other k-1 letters.
        for t in range(n):
            ways_prefix = count(t, m - 1, k, prefix_pattern)
            if not ways_prefix:
                continue
            suffix_length = n - t - 1

            if prefix_pattern[-1] == last:
                # The distinguished prefix is completed at the last letter.
                ways_suffix = onto(q, suffix_length)
            elif last not in prefix_pattern:
                # The prefix already greedily matches prefix_pattern[:-1];
                # the suffix needs its final letter, then all other letters.
                ways_suffix = tail_after_first(
                    prefix_pattern[-1], q, suffix_length
                )
            else:
                # A last inside the prefix pattern cannot be completed before
                # or after its final occurrence.
                continue

            answer = (answer + ways_prefix * ways_suffix) % mod

        return answer

    return count(N, M, K, tuple(X))

