def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    """Count monotone unit-step paths whose vertices avoid the rectangular hole."""
    mod = 998244353
    if (W + 1) * (H + 1) <= 3_000_000:
        row = [0] * (H + 1)
        ans = 0
        for x in range(W + 1):
            left = 0
            for y in range(H + 1):
                if L <= x <= R and D <= y <= U:
                    row[y] = 0
                    left = 0
                    continue
                v = 1 + left + row[y]
                if v >= mod:
                    v -= mod
                row[y] = left = v
                ans += v
            ans %= mod
        return ans

    nmax = W + H + 2
    fact = [1] * (nmax + 1)
    for i in range(1, nmax + 1):
        fact[i] = fact[i - 1] * i % mod
    invfact = [1] * (nmax + 1)
    invfact[nmax] = pow(fact[nmax], mod - 2, mod)
    for i in range(nmax, 0, -1):
        invfact[i - 1] = invfact[i] * i % mod

    def C(n, k):
        if k < 0 or k > n or n < 0:
            return 0
        return fact[n] * invfact[k] % mod * invfact[n - k] % mod

    def f_full(x, y):
        if x < 0:
            return 0
        return (C(x + y + 2, x + 1) - 1) % mod

    def F(a, b):
        if a < 0 or b < 0:
            return 0
        return (C(a + b + 2, a + 1) - 1) % mod

    def full_prefix_sum(xmax, ymax):
        if xmax < 0 or ymax < 0:
            return 0
        term = C(ymax + 3, 2)
        ans = 0
        for x in range(xmax + 1):
            ans = (ans + term - (ymax + 2)) % mod
            if x != xmax:
                term = term * (x + ymax + 4) % mod
                term = term * fact[x + 2] % mod * invfact[x + 3] % mod
        return ans

    def full_bottom_strip(xlo, xhi, yhi):
        if xlo > xhi or yhi < 0:
            return 0
        ans = 0
        term = C(xlo + yhi + 3, xlo + 2)
        for x in range(xlo, xhi + 1):
            ans = (ans + term - (yhi + 2)) % mod
            if x != xhi:
                term = term * (x + yhi + 4) % mod
                term = term * fact[x + 2] % mod * invfact[x + 3] % mod
        return ans

    def bottom_boundary_sum(xlo, xhi, ylo, yhi, value_at):
        if xlo > xhi or ylo > yhi:
            return 0
        qmax = yhi - ylo
        ans = 0
        for t in range(xlo, xhi + 1):
            ans = (ans + value_at(t) * F(xhi - t, qmax)) % mod
        return ans

    def left_boundary_sum(xlo, ylo, yhi, value_at):
        if xlo == 0 or ylo > yhi:
            return 0
        ans = 0
        pmax = W - xlo
        for k in range(ylo, yhi + 1):
            ans = (ans + value_at(k) * F(pmax, yhi - k)) % mod
        return ans

    ans = full_prefix_sum(L - 1, H)
    ans += full_bottom_strip(L, W, D - 1)
    if R < W and D <= U:
        ans += full_prefix_sum(W - R - 1, U - D)
        ans += bottom_boundary_sum(R + 1, W, D, U, lambda x: f_full(x, D - 1))
    if U < H:
        ans += full_prefix_sum(W - L, H - U - 1)
        ans += left_boundary_sum(L, U + 1, H, lambda y: f_full(L - 1, y))
        if R < W:
            ans += bottom_boundary_sum(R + 1, W, U + 1, H, lambda x: f_full(x, U))
    return ans % mod

