from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles containing the points."""
    def locate(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return (i, j, 0, y - j * K)
        return (i, j, 1, x - i * K)

    start, goal = locate(S_x, S_y), locate(T_x, T_y)
    if start == goal:
        return 0
    di, dj = abs(goal[0] - start[0]), abs(goal[1] - start[1])
    if di + dj > 10:
        return di + dj + (K - 1) * (abs(di - dj) // 2)

    imin, imax = sorted((start[0], goal[0]))
    jmin, jmax = sorted((start[1], goal[1]))
    imin -= 10
    imax += 10
    jmin -= 10
    jmax += 10
    values = sorted({0, K - 1, start[3], goal[3]})

    def neighbors(s):
        i, j, o, q = s
        if o == 0:
            for v in values:
                if v != q:
                    yield (i, j, 0, v), abs(v - q)
            if i > imin:
                yield (i - 1, j, 1, K - 1), 1
            if i < imax:
                yield (i + 1, j, 1, 0), 1
            if q == K - 1 and j < jmax:
                for v in values:
                    yield (i, j + 1, 1, v), 1
            if q == 0 and j > jmin:
                for v in values:
                    yield (i, j - 1, 1, v), 1
        else:
            for v in values:
                if v != q:
                    yield (i, j, 1, v), abs(v - q)
            if j > jmin:
                yield (i, j - 1, 0, K - 1), 1
            if j < jmax:
                yield (i, j + 1, 0, 0), 1
            if q == K - 1 and i < imax:
                for v in values:
                    yield (i + 1, j, 0, v), 1
            if q == 0 and i > imin:
                for v in values:
                    yield (i - 1, j, 0, v), 1

    dist, heap = {start: 0}, [(0, start)]
    while heap:
        d, s = heappop(heap)
        if d != dist[s]:
            continue
        if s == goal:
            return d
        for n, w in neighbors(s):
            nd = d + w
            if nd < dist.get(n, 10**100):
                dist[n] = nd
                heappush(heap, (nd, n))
    return di + dj

