            step = 1 if goal[0] > start[0] else -1
            extra = 0
            if start[2] == 1:
                extra += K - 1 - start[3] if step > 0 else start[3]
            if goal[2] == 1:
                extra += goal[3] if step > 0 else K - 1 - goal[3]
            return bulk + extra
        return bulk

    imin, imax = sorted((start[0], goal[0]))
    jmin, jmax = sorted((start[1], goal[1]))
